import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';

const badge = fileURLToPath(new URL('../src/badge.ts', import.meta.url));

test('a new badge process shows the label saved to the selected file', (t) => {
  const workspace = mkdtempSync(fileURLToPath(new URL('./badge-contract-', import.meta.url)));
  t.after(() => rmSync(workspace, { recursive: true, force: true }));

  const savedFile = join(workspace, 'saved.json');
  const missingFile = join(workspace, 'missing.json');
  const label = 'Night shift';

  function runBadge(file: string, operation: 'set' | 'show', ...args: string[]) {
    const result = spawnSync(process.execPath, [badge, file, operation, ...args], {
      cwd: workspace,
      encoding: 'utf8',
      timeout: 5_000,
    });
    assert.ifError(result.error);
    assert.equal(result.status, 0, `${operation} ${file}: ${result.stderr}`);
    return result.stdout;
  }

  runBadge(savedFile, 'set', label);
  assert.equal(runBadge(savedFile, 'show'), `${label}\n`);
  assert.equal(runBadge(missingFile, 'show'), 'Default\n');
});
